#!/bin/bash

# Check arguments
if [ $# -lt 1 ]; then
    echo "Usage: $0 <design_name> [--flags]"
    echo "Example: $0 aes --iteration 80"
    exit 1
fi

design_name=$1
shift

# Resolve workspace directory to absolute path (directory of this script)
workspace_dir="$(cd "$(dirname "$0")" && pwd)"

# Input DEF generated by run.sh
modified_def="${workspace_dir}/${design_name}.sol.def"

if [ ! -f "$modified_def" ]; then
    echo "Error: ${modified_def} not found. Please run run.sh first to generate it."
    exit 1
fi

# Build LEF list (tech LEF + stdcell/SRAM LEFs under testcases/ASAP7)
tech_lef="${workspace_dir}/testcases/ASAP7/techlef/asap7_tech_1x_201209.lef"
if [ ! -f "$tech_lef" ]; then
    echo "Error: Tech LEF not found: $tech_lef"
    exit 1
fi

cell_lefs=$(ls "${workspace_dir}/testcases/ASAP7/LEF/"*.lef 2>/dev/null | tr '\n' ',' | sed 's/,$//')
lef_arg="$tech_lef"
if [ -n "$cell_lefs" ]; then
    lef_arg="$lef_arg,$cell_lefs"
fi

echo "=========================================="
echo "HPWL Optimization"
echo "=========================================="
echo "Design: $design_name"
echo "Input DEF: $modified_def"
echo "LEF(s): $lef_arg"
echo "=========================================="

# Run DREAMPlace HPWL minimization (forward extra CLI flags)
python3 "${workspace_dir}/DREAMPlace/minimize_hpwl.py" "$modified_def" "$lef_arg" "$@"
if [ $? -ne 0 ]; then
    echo "Error: HPWL minimization failed"
    exit 1
fi

# DREAMPlace writes result to results/<design>.sol/<design>.sol.gp.def
final_def="${workspace_dir}/results/${design_name}.sol/${design_name}.sol.gp.def"
if [ -f "$final_def" ]; then
    cp "$final_def" "$modified_def"
    echo "Final optimized DEF copied to: $modified_def"
else
    echo "Warning: Final DEF not found at expected location: $final_def"
    echo "Preserving the existing DEF: $modified_def"
fi

echo ""
echo "=========================================="
echo "HPWL OPTIMIZATION COMPLETED"
echo "=========================================="
echo "Output file: ${design_name}.sol.def"
echo "==========================================" 

